<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SnapFrame — Capture, Create & Share What You Love</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: #111;
  background: #fff;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* ========== HEADER ========== */
.header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  background: rgba(255,255,255,0.92); backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  padding: 0 24px; height: 64px;
  display: flex; align-items: center; justify-content: space-between;
}
.header-logo {
  font-size: 1.35rem; font-weight: 800; letter-spacing: -0.02em;
  background: linear-gradient(135deg, #7638FA, #C44DFF);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.header-actions { display: flex; align-items: center; gap: 16px; }
.btn-login {
  padding: 9px 22px; border-radius: 24px; font-weight: 600; font-size: 0.9rem;
  background: #111; color: #fff; border: none; cursor: pointer;
  transition: opacity 0.2s;
}
.btn-login:hover { opacity: 0.85; }

/* Hamburger */
.hamburger {
  display: none; flex-direction: column; gap: 5px;
  background: none; border: none; cursor: pointer; padding: 4px;
  z-index: 110;
}
.hamburger span {
  display: block; width: 24px; height: 2.5px; background: #111;
  border-radius: 2px; transition: transform 0.25s, opacity 0.25s;
}
.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

/* Mobile nav overlay */
.mobile-nav {
  display: none; position: fixed; inset: 0; z-index: 105;
  background: rgba(255,255,255,0.98); backdrop-filter: blur(12px);
  padding: 100px 32px 40px;
  flex-direction: column; gap: 8px;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  font-size: 1.5rem; font-weight: 600; color: #111; text-decoration: none;
  padding: 12px 0; border-bottom: 1px solid rgba(0,0,0,0.06);
}

/* ========== HERO ========== */
.hero {
  min-height: 100vh; display: flex; align-items: center; justify-content: center;
  background: linear-gradient(160deg, #F5F0FF 0%, #FFF3F0 25%, #FFF0F7 50%, #F3F0FF 75%, #FFF5F0 100%);
  padding: 120px 24px 80px; text-align: center; position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: -30%; right: -15%;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(118,56,250,0.12) 0%, transparent 70%);
  border-radius: 50%;
}
.hero::after {
  content: ''; position: absolute; bottom: -20%; left: -10%;
  width: 500px; height: 500px;
  background: radial-gradient(circle, rgba(255,122,0,0.1) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-content { position: relative; z-index: 1; max-width: 800px; }
.hero-badge {
  display: inline-block; padding: 6px 18px; border-radius: 20px;
  background: rgba(118,56,250,0.1); color: #7638FA;
  font-weight: 600; font-size: 0.85rem; margin-bottom: 28px;
}
.hero h1 {
  font-size: clamp(2.5rem, 6vw, 4.5rem); font-weight: 900; letter-spacing: -0.025em;
  line-height: 1.08; margin-bottom: 24px;
  background: linear-gradient(135deg, #111 30%, #7638FA 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: clamp(1.05rem, 2vw, 1.25rem); color: #555; max-width: 560px;
  margin: 0 auto 36px; line-height: 1.6;
}
.btn-primary {
  display: inline-block; padding: 14px 40px; border-radius: 28px;
  background: linear-gradient(135deg, #7638FA, #C44DFF);
  color: #fff; font-weight: 700; font-size: 1.05rem; border: none; cursor: pointer;
  text-decoration: none; transition: transform 0.2s, box-shadow 0.2s;
  box-shadow: 0 4px 20px rgba(118,56,250,0.35);
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(118,56,250,0.45); }

/* ========== SECTIONS GENERAL ========== */
.section { padding: 100px 24px; }
.section-label {
  display: inline-block; font-size: 0.8rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.06em; color: #7638FA; margin-bottom: 16px;
}
.section-heading {
  font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; letter-spacing: -0.02em;
  line-height: 1.15; margin-bottom: 20px;
}
.section-text {
  font-size: 1.1rem; color: #555; max-width: 600px; line-height: 1.65;
}
.section-link {
  display: inline-flex; align-items: center; gap: 6px; margin-top: 20px;
  color: #7638FA; font-weight: 600; text-decoration: none; font-size: 1rem;
  transition: gap 0.2s;
}
.section-link:hover { gap: 10px; }
.section-link svg { width: 16px; height: 16px; }

/* ========== FEATURES ========== */
.features { background: #fff; }
.features-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px; max-width: 1100px; margin: 0 auto;
}
.feature-card {
  padding: 40px 28px; border-radius: 20px; border: 1px solid rgba(0,0,0,0.06);
  transition: transform 0.25s, box-shadow 0.25s;
}
.feature-card:hover { transform: translateY(-4px); box-shadow: 0 16px 40px rgba(0,0,0,0.06); }
.feature-icon {
  width: 52px; height: 52px; border-radius: 16px; margin-bottom: 20px;
  display: flex; align-items: center; justify-content: center; font-size: 1.5rem;
}
.feature-icon.clips { background: rgba(118,56,250,0.1); color: #7638FA; }
.feature-icon.stories { background: rgba(255,122,0,0.1); color: #FF7A00; }
.feature-icon.dms { background: rgba(196,77,255,0.1); color: #C44DFF; }
.feature-icon.search { background: rgba(255,77,143,0.1); color: #FF4D8F; }
.feature-card h3 { font-size: 1.2rem; font-weight: 700; margin-bottom: 8px; }
.feature-card p { font-size: 0.95rem; color: #666; line-height: 1.55; }

/* ========== SAFETY ========== */
.safety {
  background: linear-gradient(180deg, #FAF8FF 0%, #FAFAFA 100%);
  position: relative; overflow: hidden;
}
.safety-inner {
  max-width: 1100px; margin: 0 auto; display: grid;
  grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
}
.safety-visual {
  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
}
.safety-tile {
  padding: 28px 20px; border-radius: 16px; background: #fff;
  border: 1px solid rgba(0,0,0,0.05); text-align: center;
}
.safety-tile .tile-icon { font-size: 1.8rem; margin-bottom: 8px; }
.safety-tile .tile-label { font-weight: 600; font-size: 0.9rem; }

/* ========== CREATORS ========== */
.creators { background: #fff; }
.creators-inner {
  max-width: 1100px; margin: 0 auto; display: grid;
  grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
}
.creators-visual {
  display: flex; gap: 16px; flex-wrap: wrap;
}
.creator-stat {
  flex: 1; min-width: 140px; padding: 32px 24px; border-radius: 20px;
  background: linear-gradient(135deg, #7638FA, #8B5CFF);
  color: #fff; text-align: center;
}
.creator-stat.alt { background: linear-gradient(135deg, #FF7A00, #FF9A40); }
.creator-stat .stat-num { font-size: 2rem; font-weight: 900; }
.creator-stat .stat-label { font-size: 0.9rem; opacity: 0.9; margin-top: 4px; }

/* ========== TAGLINE BANNER ========== */
.tagline-banner {
  padding: 80px 24px; text-align: center;
  background: linear-gradient(135deg, #7638FA, #C44DFF, #FF7A00);
  color: #fff;
}
.tagline-banner h2 {
  font-size: clamp(2rem, 4.5vw, 3.5rem); font-weight: 900;
  letter-spacing: -0.02em; max-width: 700px; margin: 0 auto;
}

/* ========== NEWS ========== */
.news { background: #FAFAFA; overflow: hidden; }
.news-header {
  max-width: 1100px; margin: 0 auto 40px;
  display: flex; align-items: flex-end; justify-content: space-between;
  flex-wrap: wrap; gap: 16px;
}
.news-header .view-more {
  color: #7638FA; font-weight: 600; text-decoration: none; white-space: nowrap;
}
.news-carousel-wrapper { position: relative; max-width: 1200px; margin: 0 auto; }
.news-carousel {
  display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; padding: 0 24px 20px; -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.news-carousel::-webkit-scrollbar { display: none; }
.news-card {
  flex: 0 0 320px; scroll-snap-align: start;
  background: #fff; border-radius: 20px; overflow: hidden;
  border: 1px solid rgba(0,0,0,0.06);
  transition: transform 0.25s, box-shadow 0.25s;
  cursor: pointer;
}
.news-card:hover { transform: translateY(-4px); box-shadow: 0 16px 40px rgba(0,0,0,0.08); }
.news-card-thumb {
  height: 180px; display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}
.news-card-thumb.t1 { background: linear-gradient(135deg, #7638FA, #C44DFF); }
.news-card-thumb.t2 { background: linear-gradient(135deg, #FF7A00, #FFB340); }
.news-card-thumb.t3 { background: linear-gradient(135deg, #C44DFF, #FF4D8F); }
.news-card-thumb.t4 { background: linear-gradient(135deg, #2D8CFF, #7638FA); }
.news-card-thumb .thumb-icon { font-size: 3rem; opacity: 0.6; }
.news-card-body { padding: 20px; }
.news-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
.news-tag {
  font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.03em;
  padding: 3px 10px; border-radius: 10px;
}
.news-tag.announcements { background: rgba(118,56,250,0.1); color: #7638FA; }
.news-tag.tips { background: rgba(255,122,0,0.1); color: #FF7A00; }
.news-tag.product { background: rgba(45,140,255,0.1); color: #2D8CFF; }
.news-tag.safety-tag { background: rgba(34,197,94,0.1); color: #22C55E; }
.news-card-title {
  font-size: 1rem; font-weight: 700; line-height: 1.35; margin-bottom: 8px;
}
.news-card-date { font-size: 0.8rem; color: #999; }
.carousel-arrows { display: flex; gap: 8px; position: absolute; right: 24px; top: -64px; }
.carousel-arrow {
  width: 40px; height: 40px; border-radius: 50%; border: 1px solid rgba(0,0,0,0.1);
  background: #fff; cursor: pointer; display: flex; align-items: center; justify-content: center;
  transition: background 0.2s;
}
.carousel-arrow:hover { background: #f5f5f5; }
.carousel-arrow:disabled { opacity: 0.3; cursor: default; }

/* ========== CTA DOWNLOAD ========== */
.cta-download {
  text-align: center; padding: 100px 24px;
  background: linear-gradient(160deg, #111 0%, #1a1025 50%, #111 100%);
  color: #fff;
}
.cta-download h2 {
  font-size: clamp(2rem, 4.5vw, 3.5rem); font-weight: 900;
  letter-spacing: -0.02em; margin-bottom: 8px;
}
.cta-download p {
  font-size: 1.15rem; color: rgba(255,255,255,0.6); margin-bottom: 36px;
}
.cta-buttons { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
.btn-store {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 14px 28px; border-radius: 28px;
  border: 1.5px solid rgba(255,255,255,0.25);
  background: rgba(255,255,255,0.06); color: #fff;
  font-weight: 600; font-size: 0.95rem; cursor: pointer;
  text-decoration: none; transition: background 0.2s, border-color 0.2s;
}
.btn-store:hover { background: rgba(255,255,255,0.12); border-color: rgba(255,255,255,0.4); }
.btn-store svg { width: 22px; height: 22px; }

/* ========== FOOTER ========== */
.footer {
  background: #111; color: #fff; padding: 80px 24px 40px;
}
.footer-grid {
  max-width: 1100px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(6, 1fr); gap: 32px;
}
.footer-col h4 {
  font-size: 0.8rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.05em; color: #fff; margin-bottom: 16px;
}
.footer-col ul { list-style: none; }
.footer-col a {
  color: rgba(255,255,255,0.55); text-decoration: none; font-size: 0.88rem;
  display: block; padding: 4px 0; transition: color 0.2s;
}
.footer-col a:hover { color: #fff; }
.footer-col .external::after { content: ' ↗'; font-size: 0.7rem; opacity: 0.6; }
.footer-bottom {
  max-width: 1100px; margin: 48px auto 0; padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.08);
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 20px; font-size: 0.85rem; color: rgba(255,255,255,0.45);
