.footer-social { display: flex; gap: 16px; align-items: center; }
.footer-social a { color: rgba(255,255,255,0.4); transition: color 0.2s; }
.footer-social a:hover { color: #fff; }
.footer-social svg { width: 20px; height: 20px; }
.footer-legal { display: flex; gap: 16px; flex-wrap: wrap; }
.footer-legal a { color: rgba(255,255,255,0.4); text-decoration: none; font-size: 0.82rem; }
.footer-legal a:hover { color: rgba(255,255,255,0.7); }
.lang-select {
  background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.6); padding: 6px 12px; border-radius: 8px;
  font-size: 0.85rem; cursor: pointer;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .hamburger { display: flex; }
  .header-actions .btn-login { display: none; }
  .mobile-nav .btn-login-mobile {
    display: inline-block; margin-top: 8px; padding: 10px 24px;
    border-radius: 24px; background: #111; color: #fff; font-weight: 600;
    text-decoration: none; font-size: 0.95rem;
  }
  .safety-inner, .creators-inner { grid-template-columns: 1fr; gap: 40px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-bottom { flex-direction: column; text-align: center; }
  .news-card { flex: 0 0 280px; }
}
@media (max-width: 480px) {
  .header { padding: 0 16px; }
  .hero { padding: 100px 16px 60px; }
  .section { padding: 60px 16px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 24px; }
