<script>
(function() {
  // --- Hamburger Menu Toggle ---
  var hamburger = document.getElementById('hamburger');
  var mobileNav = document.getElementById('mobileNav');
  var mobileLinks = mobileNav.querySelectorAll('a');

  hamburger.addEventListener('click', function() {
    var isOpen = mobileNav.classList.toggle('open');
    hamburger.classList.toggle('active', isOpen);
    document.body.style.overflow = isOpen ? 'hidden' : '';
  });

  mobileLinks.forEach(function(link) {
    link.addEventListener('click', function() {
      mobileNav.classList.remove('open');
      hamburger.classList.remove('active');
      document.body.style.overflow = '';
    });
  });

  // --- News Carousel ---
  var carousel = document.getElementById('newsCarousel');
  var scrollLeftBtn = document.getElementById('scrollLeft');
  var scrollRightBtn = document.getElementById('scrollRight');

  function updateArrowState() {
    var tolerance = 2;
    scrollLeftBtn.disabled = carousel.scrollLeft <= tolerance;
    scrollRightBtn.disabled = carousel.scrollLeft + carousel.clientWidth >= carousel.scrollWidth - tolerance;
  }

  scrollLeftBtn.addEventListener('click', function() {
    carousel.scrollBy({ left: -340, behavior: 'smooth' });
  });

  scrollRightBtn.addEventListener('click', function() {
    carousel.scrollBy({ left: 340, behavior: 'smooth' });
  });

  carousel.addEventListener('scroll', updateArrowState);
  window.addEventListener('resize', updateArrowState);
  updateArrowState();

  // --- Touch / drag support for carousel ---
  var isDown = false, startX, scrollLeftStart;

  carousel.addEventListener('mousedown', function(e) {
    isDown = true;
    carousel.style.scrollBehavior = 'auto';
    startX = e.pageX - carousel.offsetLeft;
    scrollLeftStart = carousel.scrollLeft;
  });

  carousel.addEventListener('mouseleave', function() { isDown = false; });
  carousel.addEventListener('mouseup', function() {
    isDown = false;
    carousel.style.scrollBehavior = 'smooth';
  });

  carousel.addEventListener('mousemove', function(e) {
    if (!isDown) return;
    e.preventDefault();
    var x = e.pageX - carousel.offsetLeft;
    var walk = (x - startX) * 1.5;
    carousel.scrollLeft = scrollLeftStart - walk;
  });
})();

function scrollToTop() {
  window.scrollTo({ top: 0, behavior: 'smooth' });
}
</script>

